const countryCurrency={IN:"INR"};
const countryNames=new Intl.DisplayNames(["en"],{type:"region"});
const savedCatalogVersion=localStorage.getItem("infinix-catalog-version");
let products=savedCatalogVersion?JSON.parse(localStorage.getItem("infinix-products")||"[]"):[];
if(!savedCatalogVersion){localStorage.setItem("infinix-products","[]");localStorage.setItem("shoply-cart","{}");localStorage.setItem("infinix-catalog-version","2")}
let cart=JSON.parse(localStorage.getItem("shoply-cart")||"{}"),wish=JSON.parse(localStorage.getItem("shoply-wish")||"[]"),activeFilter="all",searchTerm="",visibleCount=8;
let accounts=JSON.parse(localStorage.getItem("infinix-accounts")||"[]");
let orderHistory=JSON.parse(localStorage.getItem("infinix-orders")||"[]");orderHistory.forEach(order=>{order.currency="INR"});

let country="IN",currentRole=localStorage.getItem("infinix-role")||"customer",currentUser=JSON.parse(localStorage.getItem("infinix-user")||"null");
function freeDeliveryThreshold(){return 499}
const defaultLocations={IN:{city:"New Delhi",state:"Delhi",landmark:"",postal:"110001"}};
let deliveryLocations=JSON.parse(localStorage.getItem("infinix-delivery-locations")||"{}"),deliveryLocation=deliveryLocations[country]||defaultLocations[country]||{city:countryNames.of(country),postal:""};
let pendingCheckout=false;
let activityLog=JSON.parse(localStorage.getItem("infinix-activity-log")||"[]");
let plusMembers=JSON.parse(localStorage.getItem("infinix-plus-members")||"{}");
let membershipRequests=JSON.parse(localStorage.getItem("infinix-plus-requests")||"[]");
const registeredCustomerIds=new Set(accounts.filter(account=>account.role==="customer").flatMap(account=>[account.username,account.email]).filter(Boolean).map(value=>String(value).trim().toLowerCase()));
const registeredAccountIds=new Set(accounts.flatMap(account=>[account.username,account.email]).filter(Boolean).map(value=>String(value).trim().toLowerCase()));
let membershipDataChanged=false;
Object.keys(plusMembers).forEach(key=>{if(!registeredCustomerIds.has(String(key).trim().toLowerCase())){delete plusMembers[key];membershipDataChanged=true}});
const liveRequests=membershipRequests.filter(request=>registeredCustomerIds.has(String(request.username||"").trim().toLowerCase())||registeredCustomerIds.has(String(request.email||"").trim().toLowerCase()));
if(liveRequests.length!==membershipRequests.length){membershipRequests=liveRequests;membershipDataChanged=true}
if(membershipDataChanged){localStorage.setItem("infinix-plus-members",JSON.stringify(plusMembers));localStorage.setItem("infinix-plus-requests",JSON.stringify(membershipRequests))}
if(currentUser&&currentUser.role!=="admin"&&!registeredAccountIds.has(String(currentUser.username||currentUser.email||"").trim().toLowerCase())&&!registeredAccountIds.has(String(currentUser.email||"").trim().toLowerCase())){currentUser=null;currentRole="customer";localStorage.removeItem("infinix-user");localStorage.setItem("infinix-role","customer")}
let plusPlanPrices=JSON.parse(localStorage.getItem("infinix-plus-plan-prices")||"null")||{monthly:300,quarterly:475,yearly:750};
if(!localStorage.getItem("infinix-plus-plan-prices"))localStorage.setItem("infinix-plus-plan-prices",JSON.stringify(plusPlanPrices));
let selectedPlusPlan="monthly";
let promotionSettings=JSON.parse(localStorage.getItem("infinix-promotion-settings")||"null")||{kicker:"GOOD STUFF, LOWER PRICES",title:"Today’s little obsessions.",description:"A few things we think you'll love—at prices worth a second look.",endAt:Date.now()+8*3600*1000+24*60*1000+12*1000};
if(!promotionSettings.endAt)promotionSettings.endAt=Date.now()+8*3600*1000+24*60*1000+12*1000;
if(!localStorage.getItem("infinix-promotion-settings"))localStorage.setItem("infinix-promotion-settings",JSON.stringify(promotionSettings));
let vouchers=JSON.parse(localStorage.getItem("infinix-vouchers")||"[]"),appliedVoucher=localStorage.getItem("infinix-applied-voucher")||"";
if(currentRole!=="customer"&&(!currentUser||currentUser.role!==currentRole))currentRole="customer";
let authRoleOverride=null;
const grid=document.getElementById("productGrid");
function money(n){const currency=countryCurrency[country]||"INR";let locale="en-IN";try{locale="en-"+country;return new Intl.NumberFormat(locale,{style:"currency",currency,maximumFractionDigits:2}).format(Number(n))}catch{return new Intl.NumberFormat("en-IN",{style:"currency",currency,maximumFractionDigits:2}).format(Number(n))}}
function moneyWhole(n){const currency=countryCurrency[country]||"INR";let locale="en-IN";try{locale="en-"+country;return new Intl.NumberFormat(locale,{style:"currency",currency,maximumFractionDigits:0}).format(Number(n))}catch{return new Intl.NumberFormat("en-IN",{style:"currency",currency,maximumFractionDigits:0}).format(Number(n))}}
function renderProducts(){let items=products.filter(p=>(activeFilter==="all"||p.category===activeFilter)&&(!searchTerm||(p.name+" "+p.category).toLowerCase().includes(searchTerm.toLowerCase())));items=items.slice(0,visibleCount);grid.innerHTML=items.length?items.map(p=>'<article class="product-card"><div class="product-image"><img src="'+p.image+'" alt="'+p.name+'" loading="lazy"><span class="product-badge">'+p.badge+'</span><button class="heart '+(wish.includes(p.id)?"liked":"")+'" data-wish="'+p.id+'" aria-label="Add to wishlist">'+(wish.includes(p.id)?"♥":"♡")+'</button></div><div class="product-info"><div class="product-cat">'+p.category+'</div><div class="product-name">'+p.name+'</div><div class="product-description">'+(p.description||'')+'</div>'+(productStock(p)?'<small class="stock-unavailable">Out of stock</small>':Number.isFinite(Number(p.quantity))?'<small class="stock-available">'+p.quantity+' available</small>':'')+'<div class="rating">★★★★★ <span>'+p.rating+' ('+p.reviews+')</span></div><div class="price-row"><span class="price">'+money(p.price)+'</span><span class="old-price">'+money(p.old)+'</span><button class="add-btn" data-add="'+p.id+'" aria-label="Add '+p.name+' to cart" '+(productStock(p)?'disabled title="Out of stock"':'')+'>'+(productStock(p)?'×':'+')+'</button></div></div></article>').join(""):'<div class="no-results"><b>No lovely finds just yet.</b>Try another search or category.</div>';grid.querySelectorAll(".add-btn").forEach(b=>b.style.display=currentRole==="customer"?"":"none");document.getElementById("showMore").style.display=products.filter(p=>(activeFilter==="all"||p.category===activeFilter)&&(!searchTerm||(p.name+" "+p.category).toLowerCase().includes(searchTerm.toLowerCase()))).length>visibleCount?"inline-block":"none"}
function productStock(p){const quantity=Number(p.quantity);return p.outOfStock===true||Number.isFinite(quantity)&&quantity<=0}
function removeCartProduct(product,notify=true){const id=String(product?.id);if(!id||!Object.prototype.hasOwnProperty.call(cart,id))return false;delete cart[id];saveCart();if(notify)toast("“"+product.name+"” is no longer available and was removed from your cart.");return true}
function saveCart(){localStorage.setItem("shoply-cart",JSON.stringify(cart));renderCart()}
function renderCart(){
  const ids=Object.keys(cart).map(Number).filter(id=>products.some(p=>p.id===id&&!productStock(p)));
  const count=ids.reduce((sum,id)=>sum+cart[id],0);
  const sum=ids.reduce((total,id)=>total+products.find(p=>p.id===id).price*cart[id],0);
  const threshold=freeDeliveryThreshold();
  const thresholdFree=sum>0&&(sum>=threshold||isPlusMember());
  const delivery=sum===0||thresholdFree?0:(countryCurrency[country]==="INR"?49:5);
  const voucher=vouchers.find(item=>item.code===appliedVoucher&&item.active&&(!item.membersOnly||isPlusMember())&&sum>=Number(item.minimum||0));
  const discount=voucher?Math.min(sum,Number(voucher.amount)||0):0;
  if(appliedVoucher&&!voucher){appliedVoucher="";localStorage.removeItem("infinix-applied-voucher")}
  const total=sum+delivery-discount;
  document.getElementById("cartCount").textContent=count;
  document.getElementById("cartTitleCount").textContent="("+count+")";
  document.getElementById("subtotal").textContent=money(sum);
  const voucherDiscountEl=document.getElementById("voucherDiscount"),voucherNoteEl=document.getElementById("voucherCartNote");
  if(voucherDiscountEl)voucherDiscountEl.textContent=discount?"−"+money(discount):"—";
  if(voucherNoteEl)voucherNoteEl.textContent=voucher?`${voucher.code} applied · You saved ${money(discount)}`:"Use an active voucher from the offers above.";
  document.getElementById("deliveryCost").textContent=thresholdFree?"FREE":sum?money(delivery):"—";
  document.getElementById("cartTotal").textContent=money(total);
  document.getElementById("checkoutTotal").textContent=money(total)+" →";
  document.getElementById("shippingProgress").style.width=Math.min(100,threshold?sum/threshold*100:0)+"%";
  document.getElementById("shippingMsg").textContent=thresholdFree?"You've unlocked free delivery!":sum?"Add "+money(Math.max(0,threshold-sum))+" to unlock free delivery":"Free delivery on orders of ₹499 or more";
  const box=document.getElementById("cartItems");
  box.innerHTML=ids.length?ids.map(id=>{const p=products.find(item=>item.id===id);return '<div class="cart-item"><img src="'+p.image+'" alt=""><div class="cart-item-info"><b>'+p.name+'</b><small>'+p.category+'</small><div class="cart-item-bottom"><div class="qty"><button data-qty="'+id+'" data-change="-1">−</button><span>'+cart[id]+'</span><button data-qty="'+id+'" data-change="1">+</button></div><b>'+money(p.price*cart[id])+'</b></div></div><button class="remove" data-remove="'+id+'">Remove</button></div>'}).join(""):'<div class="empty-cart"><div>♡</div><b>Your cart is taking a little break.</b><p>Add something lovely to get started.</p></div>';
}
function toast(msg){let t=document.getElementById("toast");t.textContent=msg;t.classList.add("show");setTimeout(()=>t.classList.remove("show"),2200)}
function openPanel(el){document.getElementById("overlay").classList.add("open");el.classList.add("open")}
function closePanels(){document.getElementById("overlay").classList.remove("open");document.querySelectorAll(".drawer,.modal").forEach(x=>x.classList.remove("open"))}
renderProducts();renderCart();
grid.addEventListener("click",e=>{let a=e.target.closest("[data-add]"),h=e.target.closest("[data-wish]");if(a){let id=a.dataset.add,product=products.find(p=>String(p.id)===String(id));if(!product||productStock(product)){toast("This product is out of stock");return}if(Number.isFinite(Number(product.quantity))&&(cart[id]||0)>=Number(product.quantity)){toast("That is all the available stock");return}cart[id]=(cart[id]||0)+1;saveCart();logActivity("Product added to cart",product.name);toast("Added to your cart — nice choice!")}if(h){let id=Number(h.dataset.wish);wish=wish.includes(id)?wish.filter(x=>x!==id):[...wish,id];localStorage.setItem("shoply-wish",JSON.stringify(wish));logActivity(wish.includes(id)?"Product added to wishlist":"Product removed from wishlist",products.find(p=>p.id===id)?.name||"Product");renderProducts();toast(wish.includes(id)?"Saved to your wishlist":"Removed from your wishlist")}});
document.getElementById("cartItems").addEventListener("click",e=>{let q=e.target.closest("[data-qty]"),r=e.target.closest("[data-remove]");if(q){let id=q.dataset.qty,next=(cart[id]||0)+Number(q.dataset.change),product=products.find(item=>String(item.id)===String(id));if(next<=0)delete cart[id];else if(product&&Number.isFinite(Number(product.quantity))&&next>Number(product.quantity)){toast("That is all the available stock");return}else cart[id]=next;saveCart()}if(r){delete cart[r.dataset.remove];saveCart()}});
