document.getElementById("authForm").onsubmit=e=>{e.preventDefault();closePanels();toast("You're all set — welcome to Shoply!");e.target.reset()};
document.getElementById("checkoutBtn").onclick=()=>{if(!Object.keys(cart).length){toast("Add something to your cart first");return}if(!deliveryLocation.street||!deliveryLocation.city||!deliveryLocation.state||!deliveryLocation.landmark||!deliveryLocation.postal){pendingCheckout=true;document.getElementById("locationBtn").click();toast("Please complete your full delivery address first");return}fillCheckoutAddress();openPanel(document.getElementById("checkoutModal"))};
document.getElementById("checkoutForm").onsubmit=e=>{e.preventDefault();const unavailable=Object.keys(cart).filter(id=>{const p=products.find(item=>String(item.id)===String(id));return !p||productStock(p)||Number.isFinite(Number(p.quantity))&&Number(cart[id])>Number(p.quantity)});if(unavailable.length){unavailable.forEach(id=>delete cart[id]);saveCart();toast("An unavailable or out-of-stock item was removed from your cart. Please review your cart.");return}const ids=Object.keys(cart).map(Number).filter(id=>products.some(p=>p.id===id));const subtotal=ids.reduce((sum,id)=>sum+products.find(p=>p.id===id).price*cart[id],0);const threshold=freeDeliveryThreshold();const freeDelivery=subtotal>0&&(subtotal>=threshold||isPlusMember());const delivery=subtotal===0||freeDelivery?0:(countryCurrency[country]==="INR"?49:5);const voucher=vouchers.find(item=>item.code===appliedVoucher&&item.active&&(!item.membersOnly||isPlusMember())&&subtotal>=Number(item.minimum||0));const discount=voucher?Math.min(subtotal,Number(voucher.amount)||0):0;const total=subtotal+delivery-discount;const identifier=currentUser?(currentUser.username||currentUser.email):"guest";const deliveryDays=isPlusMember()?1:2;orderHistory.unshift({id:Date.now(),customer:identifier,customerName:currentUser?(currentUser.name||currentUser.username):"Guest",customerEmail:e.target.querySelector('input[type="email"]').value.trim(),customerMobile:e.target.elements.mobile.value.trim(),createdAt:new Date().toISOString(),estimatedDate:new Date(Date.now()+deliveryDays*24*60*60*1000).toISOString(),status:"Processing",items:ids.map(id=>{const product=products.find(p=>p.id===id);return{productId:product.id,seller:product.seller||"",name:product.name,quantity:cart[id],price:product.price}}),subtotal,discount,voucherCode:voucher?.code||"",total,currency:countryCurrency[country],address:[e.target.elements.street.value,e.target.elements.landmark.value,e.target.elements.city.value,e.target.elements.state.value,e.target.elements.postal.value].join(", ")});orderHistory[0].items.forEach(item=>{const p=products.find(product=>String(product.id)===String(item.productId));if(p&&Number.isFinite(Number(p.quantity))){p.quantity=Math.max(0,Number(p.quantity)-Number(item.quantity));if(p.quantity===0)p.outOfStock=true}});localStorage.setItem("infinix-products",JSON.stringify(products));localStorage.setItem("infinix-orders",JSON.stringify(orderHistory));logActivity("Order placed","Order #"+orderHistory[0].id+" · "+identifier+" · "+ids.length+" product type(s)");cart={};appliedVoucher="";localStorage.removeItem("infinix-applied-voucher");saveCart();closePanels();renderProducts();renderOrderConfirmation(orderHistory[0]);openPanel(document.getElementById("orderConfirmationModal"));toast("Order placed! Your good things are on the way.");e.target.reset()};
function renderDealTimer(){const remaining=Math.max(0,Math.ceil((Number(promotionSettings.endAt)-Date.now())/1000));const h=document.getElementById("hours"),m=document.getElementById("minutes"),s=document.getElementById("seconds");if(h)h.textContent=String(Math.floor(remaining/3600)).padStart(2,"0");if(m)m.textContent=String(Math.floor(remaining%3600/60)).padStart(2,"0");if(s)s.textContent=String(remaining%60).padStart(2,"0")}
function renderPromotions(){const kicker=document.getElementById("dealKicker"),title=document.getElementById("dealTitle"),description=document.getElementById("dealDescription"),container=document.getElementById("publicVouchers");if(kicker)kicker.textContent=promotionSettings.kicker;if(title)title.textContent=promotionSettings.title;if(description)description.textContent=promotionSettings.description;if(!container)return;const active=vouchers.filter(v=>v.active&&(!v.membersOnly||isPlusMember()));const locked=vouchers.some(v=>v.active&&v.membersOnly)&&!isPlusMember();container.innerHTML=active.map(v=>`<button type="button" class="public-voucher" data-copy-voucher="${escapeAdminText(v.code)}"><b>${escapeAdminText(v.code)}</b><span>Save ${money(v.amount)}${Number(v.minimum)>0?` on orders over ${money(v.minimum)}`:" on your order"}</span><small>Tap to apply</small></button>`).join("")+(locked?'<div class="public-voucher locked-member-deal"><b>✦ Infinix Plus</b><span>Members-only offers are waiting for members.</span><small>Join Plus to unlock</small></div>':"");container.querySelectorAll("[data-copy-voucher]").forEach(button=>button.onclick=()=>{const input=document.getElementById("voucherCodeInput"),apply=document.getElementById("applyVoucherBtn");if(input)input.value=button.dataset.copyVoucher;openPanel(document.getElementById("cartDrawer"));if(apply)apply.click()})}
try{renderPromotions();renderDealTimer()}catch(error){console.error("Promotions could not load:",error)}
setInterval(()=>{try{renderDealTimer()}catch(error){console.error("Deal timer could not update:",error)}},1000);
